using System.Diagnostics;
using MarqSpec.FuturesLiquidityDashboard.Api.Auth;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;

namespace MarqSpec.FuturesLiquidityDashboard.IntegrationTests;

/// <summary>
/// The whole API in process on the synthetic feed (ARCHITECTURE.md D-12): no deployment, no credentials, every
/// value generated by the simulator. Development mode grants the anonymous local viewer every permission.
/// </summary>
public class DashboardFactory : WebApplicationFactory<Program>
{
    protected virtual string Environment => "Development";

    protected override void ConfigureWebHost(IWebHostBuilder builder)
    {
        ArgumentNullException.ThrowIfNull(builder);
        // Environment variables are applied after appsettings.{Environment}.json, so these beat
        // Development's longer warmup. Every catalog product is still collected (D-26); the short
        // window is what lets the suite finish (D-28 keeps three days once the process has run).
        System.Environment.SetEnvironmentVariable("Feed__Provider", "Synthetic");
        System.Environment.SetEnvironmentVariable("Feed__MinHistoryHours", "0.5");
        System.Environment.SetEnvironmentVariable("Feed__WarmRegimes", "false");
        System.Environment.SetEnvironmentVariable("Feed__Synthetic__StepMs", "50");
        System.Environment.SetEnvironmentVariable("Agent__FirstRunSeconds", "0");
        System.Environment.SetEnvironmentVariable("Agent__IntervalSeconds", "5");
        System.Environment.SetEnvironmentVariable("Api__PublishMs", "100");
        builder.UseEnvironment(Environment);
        builder.UseSetting("Feed:Provider", "Synthetic");
        builder.UseSetting("Feed:MinHistoryHours", "0.5");
        builder.UseSetting("Feed:WarmRegimes", "false");
        builder.UseSetting("Feed:Synthetic:StepMs", "50");
        builder.UseSetting("Agent:FirstRunSeconds", "0");
        builder.UseSetting("Agent:IntervalSeconds", "5");
        builder.UseSetting("Api:PublishMs", "100");
        // Layouts and the feedback budget in memory only, so a run neither writes into the repository's content root nor
        // reads a file an earlier run saved. A test that needs the disk sets a temp path after this.
        builder.UseSetting("Layouts:StorePath", string.Empty);
        builder.UseSetting("Feedback:BudgetStorePath", string.Empty);
        // Real "now" sits many hours after the Globex open, so warmup replays that whole session for every
        // product. Start the clock twenty minutes after the Monday open; it still advances, so the live feed runs.
        builder.ConfigureTestServices(services =>
        {
            services.RemoveAll<TimeProvider>();
            services.AddSingleton<TimeProvider>(new ShiftedClock(new DateTimeOffset(2026, 11, 9, 23, 20, 0, TimeSpan.Zero)));
        });
    }

    /// <summary>Waits until readiness reports Healthy, so tests start from a streaming feed with warm history.</summary>
    public static async Task WaitUntilReadyAsync(HttpClient client)
    {
        ArgumentNullException.ThrowIfNull(client);
        // Every catalog product warms from the session open. On a small machine that takes longer than a minute.
        var deadline = DateTime.UtcNow.AddSeconds(180);
        while (DateTime.UtcNow < deadline)
        {
            try
            {
                using var response = await client.GetAsync(new Uri("/health/ready", UriKind.Relative)).ConfigureAwait(false);
                if (response.IsSuccessStatusCode)
                {
                    return;
                }
            }
            catch (HttpRequestException)
            {
                // The host is still inside warmup and dropped the probe.
            }
            catch (TaskCanceledException)
            {
                // Same: the probe outlived a lock held by history replay.
            }

            await Task.Delay(250).ConfigureAwait(false);
        }

        throw new TimeoutException("The API did not become ready within 180 s.");
    }
}

/// <summary>A clock that starts at <paramref name="start"/> and then follows real elapsed time.</summary>
file sealed class ShiftedClock(DateTimeOffset start) : TimeProvider
{
    private readonly long _origin = Stopwatch.GetTimestamp();

    public override DateTimeOffset GetUtcNow() => start + Stopwatch.GetElapsedTime(_origin);
}

/// <summary>Production mode with no keys: startup must fail instead of answering 401 forever.</summary>
public sealed class KeylessProductionFactory : DashboardFactory
{
    protected override string Environment => "Production";

    protected override void ConfigureWebHost(IWebHostBuilder builder)
    {
        base.ConfigureWebHost(builder);
        builder.UseSetting("Agent:Enabled", "false");
    }
}

/// <summary>Production mode: no anonymous access; two keys with different scopes (REQUIREMENTS.md §2).</summary>
public sealed class ProductionDashboardFactory : DashboardFactory
{
    public const string EsViewerKey = "synthetic-test-key-es-viewer";
    public const string AgentKey = "synthetic-test-key-agent";

    protected override string Environment => "Production";

    protected override void ConfigureWebHost(IWebHostBuilder builder)
    {
        base.ConfigureWebHost(builder);
        builder.UseSetting("Auth:Keys:0:Name", "es-viewer");
        builder.UseSetting("Auth:Keys:0:KeySha256", ApiKeyAuthenticationHandler.HashKey(EsViewerKey));
        builder.UseSetting("Auth:Keys:0:Grants:0", "view-dashboard:MES");
        builder.UseSetting("Auth:Keys:1:Name", "agent");
        builder.UseSetting("Auth:Keys:1:KeySha256", ApiKeyAuthenticationHandler.HashKey(AgentKey));
        builder.UseSetting("Auth:Keys:1:Grants:0", "read-context:*");
        builder.UseSetting("Auth:Keys:1:Grants:1", "publish-overlay:MGC");
        builder.UseSetting("Agent:Enabled", "false");
    }
}
